#!/usr/bin/env node
// Regenerates the app's design-system layer from the Firstpass Design System artifact.
//
// Inputs (copied by hand or by Claude from the Design System artifact):
//   design-system/tokens.json   colour, type, spacing, radius tokens
//   design-system/bundle.js     RinkDiagram + Pips, framework-free
//   design-system/bundle.css    component classes (.fp-rink, .fp-focus-pips, ...)
//
// Outputs (generated, do not edit by hand):
//   src/styles/tokens.css       CSS custom properties, light + dark
//   src/styles/ds-bundle.css    copy of bundle.css
//   src/lib/ds/bundle.mjs       bundle.js wrapped as an ES module
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => readFileSync(join(root, p), 'utf8');
const write = (p, s) => { mkdirSync(dirname(join(root, p)), { recursive: true }); writeFileSync(join(root, p), s); };
const HEADER = '/* Generated by scripts/sync-design-system.mjs from design-system/. Do not edit. */\n';

const t = JSON.parse(read('design-system/tokens.json'));
const light = [], dark = [];
for (const c of t.color.tokens) { light.push(`  --${c.name}: ${c.value.light};`); dark.push(`  --${c.name}: ${c.value.dark};`); }
const scalar = [];
for (const group of ['spacing', 'radius', 'opacity', 'zIndex']) {
  for (const tok of t[group]?.tokens ?? []) {
    const v = typeof tok.value === 'number' && group !== 'zIndex' ? `${tok.value}px` : tok.value;
    scalar.push(`  --${tok.name}: ${v};`);
  }
}
const fam = t.type.families;
scalar.push(`  --font-display: '${fam.display}', var(--font-display-next, ui-sans-serif), system-ui, sans-serif;`);
scalar.push(`  --font-body: '${fam.body}', var(--font-body-next, ui-sans-serif), system-ui, sans-serif;`);
scalar.push(`  --font-mono: '${fam.mono}', var(--font-mono-next, ui-monospace), ui-monospace, monospace;`);

write('src/styles/tokens.css', HEADER +
  `:root {\n${light.join('\n')}\n${scalar.join('\n')}\n  color-scheme: light;\n}\n` +
  `@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="light"]) {\n${dark.map((l) => '  ' + l).join('\n')}\n    color-scheme: dark;\n  }\n}\n` +
  `:root[data-theme="dark"] {\n${dark.join('\n')}\n  color-scheme: dark;\n}\n`);

write('src/styles/ds-bundle.css', HEADER + read('design-system/bundle.css'));

write('src/lib/ds/bundle.mjs', '/* eslint-disable */\n' + HEADER +
  '// The design-system bundle expects a browser `window`; give it a private one so it also runs on the server.\n' +
  'const window = {};\n' + read('design-system/bundle.js') + '\nexport const firstpass = window.firstpass;\n');

console.log('Design system synced: tokens.css, ds-bundle.css, lib/ds/bundle.mjs');
